// sotc_decomp::install: each adapter over its slot while the slot still holds the recompiled function
uint32_t a8InstallAdapters(PS2Runtime &runtime)
{
    uint32_t n = 0;
    for (uint32_t i = 0; i < 26u; ++i)
        if (runtime.lookupFunction(kA8Ad[i].addr) == kA8Ad[i].rec)
        {
            runtime.registerFunction(kA8Ad[i].addr, kA8Ad[i].ad);
            ++n;
        }
    return n;
}
